vi.mock('next/config', () => ({
  default: () => ({
    publicRuntimeConfig: {},
    serverRuntimeConfig: {},
  }),
}));

import { vi, describe, it, expect, beforeEach } from 'vitest';
import { saveBoardArticle, deleteBoardArticle } from '../boardActions';
import client from '@/lib/api/client';
import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

vi.mock('next/headers', () => ({
  cookies: vi.fn(),
}));

vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
}));

vi.mock('@/lib/api/client', () => ({
  default: {
    post: vi.fn(),
    put: vi.fn(),
    delete: vi.fn(),
  },
}));

describe('boardActions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('saveBoardArticle', () => {
    it('should return error if title is missing', async () => {
      const formData = new FormData();
      formData.append('nttCn', 'content');
      formData.append('bbsId', 'BBS_001');

      const result = await saveBoardArticle({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('제목을 입력해주세요.');
      expect(result.field).toBe('nttSj');
    });

    it('should return error if content is missing', async () => {
      const formData = new FormData();
      formData.append('nttSj', 'title');
      formData.append('bbsId', 'BBS_001');

      const result = await saveBoardArticle({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('내용을 입력해주세요.');
      expect(result.field).toBe('nttCn');
    });

    it('should call API and return success on create', async () => {
      const formData = new FormData();
      formData.append('nttSj', 'title');
      formData.append('nttCn', 'content');
      formData.append('bbsId', 'BBS_001');

      const mockCookies = {
        get: vi.fn().mockReturnValue({ value: 'token' }),
      };
      (vi.mocked(cookies)).mockResolvedValue(mockCookies as any);

      (vi.mocked(client.post)).mockResolvedValue('100');

      const result = await saveBoardArticle({}, formData);

      expect(client.post).toHaveBeenCalled();
      expect(revalidatePath).toHaveBeenCalledWith('/admin/community/boards/selectBoardList');
      expect(result.success).toBe(true);
      expect(result.message).toBe('게시글이 성공적으로 등록되었습니다.');
      expect(result.redirect).toBe('/admin/community/boards/detail?bbsId=BBS_001&nttId=100');
    });

    it('should call API and return success on edit', async () => {
      const formData = new FormData();
      formData.append('nttId', '100');
      formData.append('nttSj', 'title edited');
      formData.append('nttCn', 'content edited');
      formData.append('bbsId', 'BBS_001');

      const mockCookies = {
        get: vi.fn().mockReturnValue({ value: 'token' }),
      };
      (vi.mocked(cookies)).mockResolvedValue(mockCookies as any);

      (vi.mocked(client.put)).mockResolvedValue({ success: true });

      const result = await saveBoardArticle({}, formData);

      expect(client.put).toHaveBeenCalledWith('/bbs/BBS_001/100', expect.any(FormData), expect.objectContaining({
        headers: { Authorization: 'Bearer token', 'Content-Type': 'multipart/form-data' }
      }));
      expect(revalidatePath).toHaveBeenCalledWith('/admin/community/boards/selectBoardList');
      expect(result.success).toBe(true);
      expect(result.message).toBe('게시글이 성공적으로 수정되었습니다.');
      expect(result.redirect).toBe('/admin/community/boards/detail?bbsId=BBS_001&nttId=100');
    });

    it('should handle API failure', async () => {
      const formData = new FormData();
      formData.append('nttSj', 'title');
      formData.append('nttCn', 'content');
      formData.append('bbsId', 'BBS_001');

      (vi.mocked(cookies)).mockResolvedValue({ get: vi.fn() } as any);
      (vi.mocked(client.post)).mockResolvedValue(null);

      const result = await saveBoardArticle({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('저장에 실패했습니다.');
    });

    it('should handle catch error', async () => {
      const formData = new FormData();
      formData.append('nttSj', 'title');
      formData.append('nttCn', 'content');
      formData.append('bbsId', 'BBS_001');

      (vi.mocked(client.post)).mockRejectedValue({
        response: { data: { message: 'Network Error' } }
      });

      const result = await saveBoardArticle({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('Network Error');
    });
  });

  describe('deleteBoardArticle', () => {
    it('should call delete API and revalidate', async () => {
      const formData = new FormData();
      formData.append('nttId', '100');
      formData.append('bbsId', 'BBS_001');

      (vi.mocked(cookies)).mockResolvedValue({ get: vi.fn().mockReturnValue({ value: 'token' }) } as any);
      (vi.mocked(client.delete)).mockResolvedValue({ success: true });

      const result = await deleteBoardArticle({}, formData);

      expect(client.delete).toHaveBeenCalledWith('/bbs/BBS_001/100', { headers: { Authorization: 'Bearer token' } });
      expect(revalidatePath).toHaveBeenCalledWith('/admin/community/boards/selectBoardList');
      expect(result.success).toBe(true);
    });

    it('should handle delete failure', async () => {
      const formData = new FormData();
      formData.append('nttId', '100');
      formData.append('bbsId', 'BBS_001');

      (vi.mocked(cookies)).mockResolvedValue({ get: vi.fn() } as any);
      (vi.mocked(client.delete)).mockResolvedValue(undefined);

      const result = await deleteBoardArticle({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('삭제에 실패했습니다.');
    });
  });
});

vi.mock('next/config', () => ({
  default: () => ({
    publicRuntimeConfig: {},
    serverRuntimeConfig: {},
  }),
}));

import { vi, describe, it, expect, beforeEach } from 'vitest';
import { saveSyncServerAction, deleteSyncServerAction, executeSyncAction } from '../syncActions';
import { syncAdminService } from '@/services/foundation/system/SyncAdminService';
import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

vi.mock('next/headers', () => ({
  cookies: vi.fn(),
}));

vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
}));

vi.mock('@/services/foundation/system/SyncAdminService', () => ({
  syncAdminService: {
    createSyncServer: vi.fn(),
    updateSyncServer: vi.fn(),
    deleteSyncServer: vi.fn(),
    executeSync: vi.fn(),
  },
}));

describe('syncActions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    (vi.mocked(cookies)).mockReturnValue({
      get: vi.fn().mockReturnValue({ value: 'token' }),
    } as any);
  });

  describe('saveSyncServerAction', () => {
    it('should create a new sync server if serverId is missing', async () => {
      const formData = new FormData();
      formData.append('serverNm', 'Test Server');
      formData.append('serverIp', '127.0.0.1');
      formData.append('serverPort', '8080');
      formData.append('targetDrctry', '/tmp');

      const result = await saveSyncServerAction({}, formData);

      expect(syncAdminService.createSyncServer).toHaveBeenCalledWith(
        expect.objectContaining({ serverNm: 'Test Server' }),
        expect.any(Object)
      );
      expect(revalidatePath).toHaveBeenCalledWith('/admin/system/sync-server');
      expect(result.success).toBe(true);
    });

    it('should update existing sync server if serverId is provided', async () => {
      const formData = new FormData();
      formData.append('serverId', 'SERVER_001');
      formData.append('serverNm', 'Updated Server');

      const result = await saveSyncServerAction({}, formData);

      expect(syncAdminService.updateSyncServer).toHaveBeenCalledWith(
        'SERVER_001',
        expect.objectContaining({ serverNm: 'Updated Server' }),
        expect.any(Object)
      );
      expect(result.success).toBe(true);
    });

    it('should handle errors', async () => {
      const formData = new FormData();
      (vi.mocked(syncAdminService.createSyncServer)).mockRejectedValue(new Error('Save Failed'));

      const result = await saveSyncServerAction({}, formData);

      expect(result.success).toBe(false);
      expect(result.message).toBe('Save Failed');
    });
  });

  describe('deleteSyncServerAction', () => {
    it('should delete sync server and revalidate', async () => {
      const result = await deleteSyncServerAction('SERVER_001');

      expect(syncAdminService.deleteSyncServer).toHaveBeenCalledWith('SERVER_001', expect.any(Object));
      expect(revalidatePath).toHaveBeenCalledWith('/admin/system/sync-server');
      expect(result.success).toBe(true);
    });
  });

  describe('executeSyncAction', () => {
    it('should execute sync and revalidate', async () => {
      const result = await executeSyncAction('SERVER_001');

      expect(syncAdminService.executeSync).toHaveBeenCalledWith('SERVER_001', expect.any(Object));
      expect(revalidatePath).toHaveBeenCalledWith('/admin/system/sync-server');
      expect(result.success).toBe(true);
    });
  });
});

'use server';

import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';
import { codeAdminService } from '@/services/foundation/system/CodeAdminService';
import { CmmnDetailCode, CmmnClCode, CmmnCode } from '@/types/foundation/system';

export async function saveCodeDetail(prevState: unknown, data: Partial<CmmnDetailCode> & { isNew?: boolean }) {
  try {
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('accessToken')?.value;
    const config = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

    const isNew = data.isNew !== false;

    if (isNew) {
      await codeAdminService.createDetailCode(data as CmmnDetailCode, config);
    } else {
      await codeAdminService.updateDetailCode(data.codeId!, data.code!, data as CmmnDetailCode, config);
    }

    revalidatePath('/admin/system/common-code');
    return { success: true, message: '상세 코드가 저장되었습니다.' };
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : '저장 중 오류 발생';
    console.error('Save Code Detail Error:', error);
    return { success: false, message };
  }
}

export async function deleteCodeDetail(prevState: unknown, { codeId, code }: { codeId: string, code: string }) {
  try {
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('accessToken')?.value;
    const config = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

    await codeAdminService.deleteDetailCode(codeId, code, config);

    revalidatePath('/admin/system/common-code');
    return { success: true, message: '상세 코드가 삭제되었습니다.' };
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : '삭제 중 오류 발생';
    console.error('Delete Code Detail Error:', error);
    return { success: false, message };
  }
}

