export async function saveDeptHierarchyAction(flattenedDepts: any[]): Promise<ActionResponse> {
  try {
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('accessToken')?.value;
    const config = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

    // 트리 구조 변경 사항을 백엔드 형식에 맞춰 매핑 (parentId -> upperOrgnztId, ordr)
    const submitData = flattenedDepts.map((item, index) => ({
      orgnztId: item.orgnztId,
      orgnztNm: item.orgnztNm,
      orgnztDc: item.orgnztDc,
      upperOrgnztId: item.parentId,
      ordr: index + 1
    }));

    await deptAdminService.updateDeptHierarchy(submitData, config);

    revalidatePath('/admin/user/departments');
    return { success: true, message: '조직 아키텍처 구조가 동기화되었습니다.' };
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : '계층 구조 저장 중 오류 발생';
    return { success: false, message };
  }
}

'use server';

import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';
import { networkAdminService, Network } from '@/services/foundation/system/NetworkAdminService';

interface ActionResponse {
    success: boolean;
    message: string;
}

export async function saveNetworkAction(prevState: unknown, formData: FormData): Promise<ActionResponse> {
    try {
        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        const ntwrkId = formData.get('ntwrkId') as string;
        const data: Partial<Network> = {
            manageIem: formData.get('manageIem') as string,
            ntwrkIp: formData.get('ntwrkIp') as string,
            gtwy: formData.get('gtwy') as string,
            subnet: formData.get('subnet') as string,
            domnServer: formData.get('domnServer') as string,
            userNm: formData.get('userNm') as string,
            useAt: formData.get('useAt') as 'Y' | 'N',
        };

        if (ntwrkId) {
            await networkAdminService.updateNetwork(ntwrkId, data, axiosConfig);
        } else {
            await networkAdminService.createNetwork(data as any, axiosConfig);
        }

        revalidatePath('/admin/system/network');
        return { success: true, message: '네트워크 정보가 저장되었습니다.' };
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : '저장 중 오류 발생';
        console.error('Save Network Error:', error);
        return { success: false, message: errorMessage };
    }
}

export async function deleteNetworkAction(id: string): Promise<ActionResponse> {
    try {
        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        await networkAdminService.deleteNetwork(id, axiosConfig);

        revalidatePath('/admin/system/network');
        return { success: true, message: '네트워크 정보가 삭제되었습니다.' };
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : '삭제 중 오류 발생';
        console.error('Delete Network Error:', error);
        return { success: false, message: errorMessage };
    }
}

'use server';

import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';
import client from '@/lib/api/client';
import { Banner, Popup } from '@/types/foundation/banner';

interface ActionResponse {
    success: boolean;
    message: string;
}

interface SaveActionParams<T> {
    mode: 'create' | 'edit';
    data: T;
    id?: string;
}

// Banner Actions
export async function saveBannerAction(prevState: unknown, { mode, data, id }: SaveActionParams<Banner>): Promise<ActionResponse> {
    try {
        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        if (mode === 'create') {
            await client.post('/admin/system/banners', data, axiosConfig);
        } else {
            await client.put(`/admin/system/banners/${id}`, data, axiosConfig);
        }

        revalidatePath('/admin/system/banner');
        revalidatePath('/');
        return { success: true, message: `배너가 ${mode === 'create' ? '등록' : '수정'}되었습니다.` };
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : '저장 중 오류 발생';
        console.error('Save Banner Error:', error);
        return { success: false, message: errorMessage };
    }
}

export async function deleteBannerAction(prevState: unknown, id: string): Promise<ActionResponse> {
    try {
        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        await client.delete(`/admin/system/banners/${id}`, axiosConfig);

        revalidatePath('/admin/system/banner');
        return { success: true, message: '배너가 삭제되었습니다.' };
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : '삭제 중 오류 발생';
        console.error('Delete Banner Error:', error);
        return { success: false, message: errorMessage };
    }
}

// Popup Actions
export async function savePopupAction(prevState: unknown, { mode, data, id }: SaveActionParams<Popup>): Promise<ActionResponse> {
    try {
        const os = require('os');
        const path = require('path');
        const fs = require('fs');
        const logPath = path.join(os.tmpdir(), 'action-debug.log');

        fs.appendFileSync(logPath, `\n[${new Date().toISOString()}] savePopupAction - mode: ${mode}, id: ${id}\n`);
        fs.appendFileSync(logPath, `Data: ${JSON.stringify(data, null, 2)}\n`);

        console.log(`>>> [Action] savePopupAction - mode: ${mode}, id: ${id}`);

        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        if (mode === 'create') {
            fs.appendFileSync(logPath, `Calling POST /admin/system/popups...\n`);
            const res: any = await client.post('/admin/system/popups', data, axiosConfig);
            fs.appendFileSync(logPath, `POST Success: ${JSON.stringify(res.data || res)}\n`);
        } else {
            fs.appendFileSync(logPath, `Calling PUT /admin/system/popups/${id}...\n`);
            const res: any = await client.put(`/admin/system/popups/${id}`, data, axiosConfig);
            fs.appendFileSync(logPath, `PUT Success: ${JSON.stringify(res.data || res)}\n`);
        }

        revalidatePath('/admin/system/banner');
        revalidatePath('/');
        return { success: true, message: `팝업이 ${mode === 'create' ? '등록' : '수정'}되었습니다.` };
    } catch (error: unknown) {
        const os = require('os');
        const path = require('path');
        const fs = require('fs');
        const logPath = path.join(os.tmpdir(), 'action-debug.log');

        const errorMessage = error instanceof Error ? error.message : '저장 중 오류 발생';
        const errorDetail = {
            message: errorMessage,
            response: error?.response?.data,
            status: error?.response?.status
        };
        fs.appendFileSync(logPath, `ERROR: ${JSON.stringify(errorDetail, null, 2)}\n`);

        console.error('>>> [Action] Save Popup Error:', errorDetail);
        return { success: false, message: error?.response?.data?.message || errorMessage };
    }
}

export async function deletePopupAction(prevState: unknown, id: string): Promise<ActionResponse> {
    try {
        const cookieStore = await cookies();
        const accessToken = cookieStore.get('accessToken')?.value;
        const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

        await client.delete(`/admin/system/popups/${id}`, axiosConfig);

        revalidatePath('/admin/system/banner');
        return { success: true, message: '팝업이 삭제되었습니다.' };
    } catch (error: unknown) {
        const errorMessage = error instanceof Error ? error.message : '삭제 중 오류 발생';
        console.error('Delete Popup Error:', error);
        return { success: false, message: errorMessage };
    }
}

