                                    {user.nm || user.userNm || user.adbkNm || user.ncrdNm}
                                  </span>
                                  <span className="text-xs text-slate-500">
                                    {user.email || user.emailAdres || user.emplyrId || user.userId || user.adbkId || user.ncrdId}
