 replyPsblYn: false,
 fileAtchPsblYn: true,
 atchPsblFileCnt: 3,
 atchPsblFileSize: 5242880, // 5MB
 bbsTypeCd: 'BBST01',
 tmplatId: 'TMPLT_HUB',
 cmntyId: '',
 permissions: {
 'ROLE_ADMIN': ['list', 'read', 'write', 'comment'],
 'ROLE_USER': ['list', 'read', 'write', 'comment'],
 'ROLE_ANONYMOUS': ['list', 'read'],
 },
 menuNm: '',
 upperMenuNo: '2000000',
 menuOrdr: 1,
