 if (currentStep === 1 && !watch('menuNm')) {
 setValue('menuNm', bbsTtl);
 }
 setCurrentStep((prev) => Math.min(prev + 1, STEPS.length));
 };
 const prevStep = () => setCurrentStep((prev) => Math.max(prev - 1, 1));

