interface CalendarTemplateProps extends TemplateProps {
  currentViewDate: Date;
  onPrevMonth: () => void;
  onNextMonth: () => void;
}

export const CalendarTemplate = ({ list, bbsId, currentViewDate, onPrevMonth, onNextMonth }: CalendarTemplateProps) => {
  const year = currentViewDate.getFullYear();
  const month = currentViewDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const postsByDay = list.reduce((acc: { [key: number]: BoardPost[] }, post) => {
    const targetDate = post.eventDate || post.createdDate;
    if (targetDate) {
      const d = new Date(targetDate);
      if (d.getFullYear() === year && d.getMonth() === month) {
        const day = d.getDate();
        if (!acc[day]) acc[day] = [];
        acc[day].push(post);
      }
    }
    return acc;
  }, {});

  return (
    <div className="p-10 space-y-10">
      <motion.div 
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        className="flex justify-between items-center bg-slate-900 p-10 rounded-[2.5rem] text-white relative overflow-hidden shadow-2xl"
      >
        <div className="absolute top-0 right-0 w-64 h-64 bg-primary/20 blur-[100px] rounded-full" />
        <div className="space-y-2 relative z-10">
          <p className="text-primary font-black tracking-[0.4em] text-[10px] uppercase">Node Timeline Matrix</p>
          <h3 className="text-5xl font-black tracking-tighter uppercase bg-clip-text text-transparent bg-gradient-to-r from-white to-white/40">
            {format(currentViewDate, "MMMM yyyy", { locale: ko })}
          </h3>
        </div>
        <div className="flex gap-4 relative z-10">
          <Button 
            variant="outline" 
            onClick={onPrevMonth}
            className="h-16 w-16 border-white/10 bg-white/5 hover:bg-white hover:text-slate-900 rounded-2xl transition-all"
            aria-label="?�전 ??
          >
            <ChevronRight className="rotate-180" size={24} />
          </Button>
          <Button 
            variant="outline" 
            onClick={onNextMonth}
            className="h-16 w-16 border-white/10 bg-white/5 hover:bg-white hover:text-slate-900 rounded-2xl transition-all"
            aria-label="?�음 ??
          >
            <ChevronRight size={24} />
          </Button>
        </div>
      </motion.div>

      <motion.div 
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-7 gap-5"
      >
        {['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'].map(d => (
          <div key={d} className="text-center font-black text-slate-300 text-[10px] tracking-[0.4em] pb-6 border-b-2 border-slate-50 uppercase">{d}</div>
        ))}
        {Array.from({ length: 42 }, (_, i) => i - firstDayOfMonth + 1).map((day, i) => {
          const isCurrentMonth = day > 0 && day <= daysInMonth;
          const dayPosts = isCurrentMonth ? postsByDay[day] || [] : [];
          const isToday = day === new Date().getDate() && month === new Date().getMonth() && year === new Date().getFullYear();

          return (
            <motion.div 
              key={i} 
              variants={itemVariants}
              className={cn(
                "min-h-[180px] p-6 border-2 transition-all relative group rounded-3xl",
                isToday ? "bg-primary/5 border-primary/30 shadow-inner" : "bg-white/40 backdrop-blur-sm border-slate-50 hover:border-slate-200 hover:shadow-xl",
                !isCurrentMonth ? "opacity-10 pointer-events-none bg-slate-50/50" : ""
              )}
            >
              <div className="flex justify-between items-start mb-6">
                <span className={cn(
                  "text-2xl font-black tracking-tighter", 
                  isToday ? "text-primary" : "text-slate-200 group-hover:text-slate-900",
                  (i % 7 === 0) && isCurrentMonth ? "text-rose-400" : "", // Sunday
                  (i % 7 === 6) && isCurrentMonth ? "text-indigo-400" : "" // Saturday
                )}>
                  {isCurrentMonth ? day : ''}
                </span>
                {dayPosts.length > 0 && (
                  <Badge className="bg-slate-900 text-white hover:bg-primary text-[10px] font-black h-6 w-6 rounded-xl p-0 flex items-center justify-center border-none shadow-lg group-hover:scale-110 transition-transform">
                    {dayPosts.length}
                  </Badge>
                )}
              </div>

              <div className="space-y-2.5 max-h-[110px] overflow-y-auto custom-scrollbar pr-1">
                {dayPosts.map((post) => (
                  <Link 
                    key={post.pstId}
                    href={`/admin/community/boards/detail?bbsId=${bbsId}&pstId=${post.pstId}`}
                    className={cn(
                      "block p-2.5 text-[10px] font-black leading-none rounded-lg shadow-sm transition-all hover:scale-105 cursor-pointer truncate uppercase tracking-tight",
                      post.noticeYn === 'Y' ? "bg-gradient-to-r from-rose-500 to-rose-600 text-white shadow-rose-500/20" : "bg-white border border-slate-100 text-slate-900 hover:bg-slate-900 hover:text-white"
                    )}
                    title={post.pstTtl}
                  >
                    {post.pstTtl}
                  </Link>
                ))}
              </div>

              {isCurrentMonth && (
                <div className="absolute bottom-5 right-6 text-[10px] font-black text-slate-100 group-hover:text-slate-200 transition-all uppercase tracking-widest opacity-0 group-hover:opacity-100">
                  {`${year}.${month + 1}.${day}`}
                </div>
              )}
            </motion.div>
          );
        })}
      </motion.div>
    </div>
  );
};

