import { 
  Users, 
  Monitor, 
  Cpu, 
  Database, 
  ShieldCheck, 
  Activity,
  ArrowRight,
  Server
} from 'lucide-react';

interface NodeProps {
  id: string;
  label: string;
  icon: React.ReactNode;
  x: number;
  y: number;
  status?: 'active' | 'warning' | 'idle';
  latency?: string;
}

const TopologyNode = ({ label, icon, x, y, status = 'active', latency }: NodeProps) => {
  const statusColor = status === 'active' ? 'text-emerald-400' : status === 'warning' ? 'text-amber-400' : 'text-slate-400';
  const glowColor = status === 'active' ? 'rgba(52, 211, 153, 0.4)' : status === 'warning' ? 'rgba(251, 191, 36, 0.4)' : 'rgba(148, 163, 184, 0.2)';

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.8 }}
      animate={{ opacity: 1, scale: 1 }}
      className="absolute flex flex-col items-center gap-3"
      style={{ left: `${x}%`, top: `${y}%`, transform: 'translate(-50%, -50%)' }}
    >
      <div className="relative">
        {/* Pulsing Aura */}
        {status === 'active' && (
          <motion.div
            animate={{ scale: [1, 1.4, 1], opacity: [0.3, 0, 0.3] }}
            transition={{ duration: 2, repeat: Infinity }}
            className="absolute inset-0 rounded-lg"
            style={{ backgroundColor: glowColor, filter: 'blur(12px)' }}
          />
        )}

        <div className="w-16 h-11 bg-slate-900/80 backdrop-blur-xl border border-white/10 rounded-lg flex items-center justify-center shadow-2xl relative z-10">
          <div className={`${statusColor}`}>
            {React.cloneElement(icon as React.ReactElement<{ size: number }>, { size: 28 })}
          </div>
        </div>
      </div>

      <div className="text-center">
        <p className="text-xs font-bold text-white uppercase tracking-tighter opacity-90">{label}</p>
        {latency && (
          <div className="flex items-center justify-center gap-1 mt-0.5">
            <Activity size={10} className="text-emerald-400" />
            <span className="text-xs text-emerald-400/80 font-medium">{latency}</span>
          </div>
        )}
      </div>
    </motion.div>
  );
};

const ConnectionLine = ({ start, end, duration = 3 }: { start: [number, number], end: [number, number], duration?: number }) => {
  return (
    <svg 
      className="absolute inset-0 w-full h-full pointer-events-none" 
      style={{ zIndex: 0 }}
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
    >
      {/* Static Base Line */}
      <line
        x1={start[0]}
        y1={start[1]}
        x2={end[0]}
        y2={end[1]}
        stroke="rgba(255,255,255,0.05)"
        strokeWidth="0.2"
      />

      {/* Animated Flow Dot */}
      <motion.circle
        r="0.5"
        fill="#34d399"
        initial={{ offsetDistance: "0%" }}
        animate={{ offsetDistance: "100%" }}
        transition={{ duration, repeat: Infinity, ease: "linear" }}
        style={{
          offsetPath: `path('M ${start[0]} ${start[1]} L ${end[0]} ${end[1]}')`,
        }}
      />

      {/* Glowing Moving Line Segment */}
      <motion.line
        x1={start[0]}
        y1={start[1]}
        x2={end[0]}
        y2={end[1]}
        stroke="url(#lineGradient)"
        strokeWidth="0.3"
        strokeDasharray="5 45"
        animate={{ strokeDashoffset: [-50, 0] }}
        transition={{ duration, repeat: Infinity, ease: "linear" }}
      />

      <defs>
        <linearGradient id="lineGradient" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="transparent" />
          <stop offset="50%" stopColor="#34d399" />
          <stop offset="100%" stopColor="transparent" />
        </linearGradient>
      </defs>
    </svg>
  );
};

