  } catch (error) {
    console.error('Failed to fetch initial reward info');
  }

  return (
    <Suspense fallback={<div className="flex items-center justify-center min-h-[400px]">로딩 중..</div>}>
      <RewardManageClient initialData={initialData} />
    </Suspense>
  );
}

