const DEPTS_KEY = ['admin', 'departments'] as const;
const ROLES_KEY = ['admin', 'authorities'] as const;

export default function DeptAuthorityPage() {
 const queryClient = useQueryClient();
 const { toast } = useToast();
 const [selectedDept, setSelectedDept] = useState<string | null>(null);
 const [searchKeyword, setSearchKeyword] = useState('');
 const [selectedAuthorCode, setSelectedAuthorCode] = useState<string | null>(null);

 const { data: deptsData, isLoading: deptsLoading } = useQuery({
 queryKey: DEPTS_KEY,
 queryFn: () => deptAdminService.getDeptList(),
 staleTime: 5 * 60 * 1000,
 });

 const { data: rolesData, isLoading: rolesLoading } = useQuery({
 queryKey: ROLES_KEY,
 queryFn: () => authorAdminService.getAuthorList(),
 staleTime: 5 * 60 * 1000,
 });

 const depts: Department[] = (deptsData as any)?.list || (deptsData as any)?.resultList || deptsData || [];
 const roles: AuthorInfo[] = (rolesData as any)?.list || (rolesData as any)?.resultList || rolesData || [];

 const filteredDepts = depts.filter(d =>
 String(d.orgnztNm || '').toLocaleLowerCase().includes(searchKeyword.toLocaleLowerCase()) ||
 String(d.orgnztId || '').toLocaleLowerCase().includes(searchKeyword.toLocaleLowerCase())
 );

 const loading = deptsLoading || rolesLoading;

 const saveMutation = useMutation({
 mutationFn: (authorCode: string) =>
 deptAuthorityAdminService.updateDeptAuthorities({
 deptId: selectedDept!,
 authorCode,
 allMembers: true
 }),
 onSuccess: () => {
 toast('부서 전체 사용자에게 보안 정책이 일괄 적용되었습니다.', 'success');
 setSelectedAuthorCode(null);
 },
 onError: () => toast('권한 저장 중 오류가 발생했습니다.', 'error')
 });

 const columns: Column<AuthorInfo>[] = [
 {
 header: '정책 프로파일 ID',
 accessor: (item: AuthorInfo) => (
 <div className="flex flex-col gap-0.5">
 <span className="text-xs font-bold text-muted-foreground/30 tracking-[0.4em] uppercase font-mono leading-none mb-1">POLICY_UID</span>
 <span className="font-mono text-xs font-bold text-primary tracking-widest uppercase">{item.authorCode}</span>
 </div>
 ),
 className: 'w-48'
 },
 {
 header: '권한 아키텍처 명칭',
 accessor: (item: AuthorInfo) => (
 <div className="flex flex-col gap-0.5 py-2">
 <span className="font-bold text-foreground tracking-tight text-md uppercase leading-tight">{item.authorNm}</span>
 <span className="text-xs font-bold text-muted-foreground/40 truncate block max-w-[300px] leading-none">{item.authorDc || '규정 명세 없음'}</span>
 </div>
 )
 },
 {
 header: 'SELECTION',
 className: 'text-center w-32',
 accessor: (item: AuthorInfo) => {
 const isSelected = selectedAuthorCode === item.authorCode;
 return (
 <div className="flex justify-center">
 <button
 type="button"
 onClick={(e) => {
 e.stopPropagation();
 setSelectedAuthorCode(item.authorCode);
 }}
 className={cn(
 "relative flex items-center justify-center w-8 h-8 rounded-lg transition-all duration-500 outline-none border-2",
 isSelected ? "bg-primary border-primary shadow-xl shadow-primary/30 rotate-0 scale-110" : "bg-white border-slate-100 hover:border-primary/40 rotate-12"
 )}
 >
 <CheckCircle size={16} className={cn("transition-all duration-700", isSelected ? "text-white scale-100 opacity-100 rotate-0" : "text-transparent scale-50 opacity-0 rotate-45")} />
 </button>
 </div>
 );
 }
 }
 ];

 const handleSave = () => {
 if (!selectedDept) {
 return toast('설정할 부서를 먼저 선택해 주세요.', 'info');
 }
 if (!selectedAuthorCode) {
 return toast('부여할 권한을 선택해 주세요.', 'info');
 }

 if (confirm(`선택한 조직의 모든 구성원에게 '${selectedAuthorCode}' 보안 정책을 전역적으로 강제 적용하시겠습니까?`)) {
 saveMutation.mutate(selectedAuthorCode);
 }
 };

 const currentDept = depts.find(d => d.orgnztId === selectedDept);

 return (
 <div className="space-y-12 pb-24 animate-in fade-in duration-1000">
