function NavButton({ icon, label, active, onClick }: { icon: React.ReactNode, label: string, active: boolean, onClick: () => void }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "w-full group p-6 rounded-lg border-2 transition-all flex items-center gap-6",
        active
          ? "bg-slate-900 border-slate-900 text-white shadow-2xl scale-[1.02] z-10"
          : "bg-white border-transparent hover:border-primary/20 text-slate-500 hover:text-slate-900"
      )}
    >
      <div className={cn(
        "w-12 h-12 rounded-lg flex items-center justify-center transition-all shadow-md",
        active ? "bg-white/10 text-white" : "bg-slate-100 text-slate-400 group-hover:bg-primary/10 group-hover:text-primary shadow-inner"
      )}>
        {icon}
      </div>
      <span className="text-xs font-bold tracking-tight">{label}</span>
    </button>
  );
}

function Bar({ height, opacity, active = false, color }: any) {
  return (
    <div className="flex-1 flex flex-col items-center gap-2 h-full justify-end">
      <motion.div
        initial={{ height: 0 }}
        animate={{ height: `${height}%` }}
        transition={{ duration: 1, ease: "easeOut" }}
        className={cn(
          "w-full rounded-t-2xl transition-all shadow-[0_-5px_20px_-5px_rgba(255,255,255,0.1)]",
          color
        )}
        style={{ opacity }}
      />
    </div>
  );
}

function DetailStat({ icon, label, value, color }: { icon: React.ReactNode, label: string, value: string, color: string }) {
  const colorMap: any = {
    primary: "text-primary bg-primary/5 border-primary/10",
    amber: "text-amber-500 bg-amber-500/5 border-amber-500/10",
    emerald: "text-emerald-500 bg-emerald-500/5 border-emerald-500/10",
    rose: "text-rose-500 bg-rose-500/5 border-rose-500/10"
  };

  return (
    <div className={cn("p-8 rounded-lg border-2 space-y-4 shadow-sm group hover:scale-105 transition-transform", colorMap[color])}>
      <div className="flex items-center gap-3">
        {icon}
        <span className="text-xs font-bold tracking-tight opacity-40 leading-none">{label}</span>
      </div>
      <p className="text-2xl font-bold tracking-tighter text-foreground leading-none tabular-nums">{value}</p>
    </div>
  );
}

