 activeTab === 'list' ? "bg-slate-900 text-white shadow-xl" : "text-slate-400 hover:bg-white/50 hover:text-slate-600"
 )}>
 <Server size={14} /> Inventory
 </button>
 <button 
 onClick={() => setActiveTab('reception')}
 className={cn(
