 <HubMetricGrid>
 <HubMetricCard title="전체 노드" value={total} icon={Database} color="primary" />
 <HubMetricCard title="활성 상태" value={data.filter(i => i.ablEnnc === '0').length || 0} icon={ShieldCheck} color="emerald" />
 <HubMetricCard title="대기 큐" value={receptionData.filter(i => i.processSe !== '1').length || 0} icon={Clock} color="amber" status={receptionData.filter(i => i.processSe !== '1').length > 0 ? "Pending" : "Normal"} />
 <HubMetricCard title="동기화망" value="안전" icon={Zap} color="indigo" />
 </HubMetricGrid>

 <HubSectionCard
 title={activeTab === 'list' ? "기관 인벤토리" : "수집 파이프라인"}
 description={activeTab === 'list' ? "모든 공공기관 노드 식별자의 활성 리스트입니다." : "지속적으로 유입되는 코드 변동 데이터의 수신 이력입니다."}
 icon={activeTab === 'list' ? Globe : Zap}
 >
 <div className="bg-white/40 backdrop-blur-md rounded-2xl border border-white/60 shadow-xl p-8 mb-8 ring-1 ring-black/5">
 <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
 <div className="flex-1">
 <div className="relative group/search max-w-xl">
 <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within/search:text-primary transition-colors" size={18} />
 <Input
