                            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-muted-foreground opacity-30 group-focus-within/search:opacity-100 transition-opacity" size={20} />
                            <Input
                                placeholder="노드 명칭 또는 ID 기반 지형 검색.."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="h-11 pl-16 pr-8 rounded-lg bg-slate-50 border-2 border-slate-100 font-bold text-md tracking-tight shadow-inner focus:ring-4 focus:ring-primary/10 transition-all"
                            />
                        </div>
                    </div>
                </div>

                <StandardDataTable 
                    columns={columns} 
                    data={filteredNodes} 
                    emptyMessage="조회된 네트워크 자산이 없습니다." 
                    className="border-none bg-transparent" 
                />
            </HubSectionCard>

            <StandardModal
                isOpen={isModalOpen}
                onClose={() => setIsOpen(false)}
                title={editingNode ? '인프라 노드 구성 편집' : '신규 네트워크 노드 프로비저닝'}
                maxWidth="3xl"
            >
                <div className="pt-4 text-left">
                    <NetworkForm 
                        initialData={editingNode || {}} 
                        onCancel={() => setIsOpen(false)}
                        onSubmit={async (values) => {
                            try {
                                const formData = new FormData();
                                Object.entries(values).forEach(([key, value]) => {
                                    if (value !== undefined) formData.append(key, String(value));
                                });

                                const res = await saveNetworkNodeAction(null, formData);
                                if (res.success) {
                                    toast(res.message, 'success');
                                    setIsOpen(false);
                                    // Note: In a real app, we might need to refresh data or use optimistic updates
                                    // Here we assume Server Action triggers revalidation or we refresh manually
                                    window.location.reload(); 
                                } else {
                                    toast(res.message, 'error');
                                }
                            } catch (error) {
                                toast('데이터 유효성 검증 및 반영에 실패했습니다.', 'error');
                            }
                        }}
                    />
                </div>
            </StandardModal>
        </div>
    );
}

import { Suspense } from 'react';
import { cookies } from 'next/headers';
import { networkAdminService, Network } from '@/services/foundation/system/NetworkAdminService';
import NetworkAdminClient from './NetworkAdminClient';

export const metadata = {
  title: '네트워크 인프라 지형 관리 및 최적화 | 전자정부 표준프레임워크',
  description: '시스템 전반의 네트워크 토폴로지 정보를 관리하고 최적의 연결성을 보장합니다',
};

async function NetworkDataContainer() {
  const cookieStore = await cookies();
  const accessToken = cookieStore.get('accessToken')?.value;
  const axiosConfig = accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : {};

  // [Eliminating Waterfalls] 서버 사이드 초기 데이터 페칭
  let initialNetworks: Network[] = [];

  try {
    const response = await networkAdminService.getNetworks({ page: 0, size: 100 }, axiosConfig);
    initialNetworks = (response as any)?.content || (response as any)?.data?.content || (response as any) || [];
  } catch (error) {
    console.error('Server-side fetch network data failed:', error);
  }

  return <NetworkAdminClient initialNetworks={initialNetworks} />;
}

export default function AdminNetworkPage() {
  return (
    <Suspense fallback={<NetworkAdminLoading />}>
      <NetworkDataContainer />
    </Suspense>
  );
}

function NetworkAdminLoading() {
  return (
    <div className="max-w-6xl mx-auto space-y-12 animate-pulse pb-24 h-[calc(100vh-120px)] flex flex-col text-left">
