import { useAppForm } from '@/hooks/useAppForm';

const programSchema = z.object({
 progrmFileNm: z.string()
 .min(1, '파일명은 필수입니다.')
 .max(60, '파일명은 60자 이내여야 합니다.'),
 progrmStrePath: z.string()
 .max(100, '경로가 너무 깁니다. (최대 100자)')
 .optional()
 .or(z.literal('')),
 progrmKoreanNm: z.string()
 .min(1, '프로그램 명칭은 필수입니다.')
 .max(60, '명칭은 60자 이내여야 합니다.'),
 url: z.string()
 .min(1, '엔드포인트 URL은 필수입니다.')
 .startsWith('/', 'URL은 /로 시작해야 합니다.')
 .max(100, 'URL은 100자 이내여야 합니다.'),
 progrmDc: z.string()
 .max(200, '설명이 너무 깁니다. (최대 200자)')
 .optional()
 .or(z.literal('')),
});

type ProgramFormValues = z.infer<typeof programSchema>;

const StandardModal = dynamic(() => import('@/app/components/ui/standard-modal').then(mod => mod.StandardModal), { ssr: false });

export default function ProgramAdminClient({ initialData, searchWrd }: { initialData: PageResponse<Program>; searchWrd: string }) {
 const { toast } = useToast();
 const confirm = useConfirm();

 const [isModalOpen, setIsOpen] = useState(false);
 const [mode, setMode] = useState<'create' | 'edit'>('create');

 const form = useAppForm(programSchema, {
 defaultValues: {
 progrmFileNm: '',
 progrmStrePath: '',
 progrmKoreanNm: '',
 url: '',
 progrmDc: ''
 }
 });

 const [data, setData] = useState<Program[]>(() => {
 return (initialData?.list || []) as Program[];
 });
 const [total, setTotal] = useState<number>(() => {
 return initialData?.total || 0;
 });
 const [loading, setLoading] = useState(false);
 const [currentSearchWrd, setCurrentSearchWrd] = useState(searchWrd);

 const loadData = async (wrd: string = currentSearchWrd, page: number = 1) => {
 try {
 setLoading(true);
 const res = await programAdminService.getProgramList({ page: page - 1, size: 10, searchWrd: wrd });

 const list = (res.list || []) as Program[];
 const totalCount = res.total || 0;

 setData(list);
 setTotal(totalCount);
 } catch (error: unknown) {
 toast('데이터를 불러오는 중 오류가 발생했습니다.', 'error');
 } finally {
 setLoading(false);
 }
 };

 const handleOpenCreate = () => {
 setMode('create');
 form.reset({ progrmFileNm: '', progrmStrePath: '', progrmKoreanNm: '', url: '', progrmDc: '' });
 setIsOpen(true);
 };

 const handleOpenEdit = (program: Program) => {
 setMode('edit');
 form.reset(program);
 setIsOpen(true);
 };


 const handleDelete = async (name: string) => {
 const isConfirmed = await confirm({
 title: '프로그램 삭제',
 message: `[${name}] 프로그램을 삭제하시겠습니까? 해당 프로그램과 연결된 모든 메뉴 연동이 해제될 수 있습니다.`,
 variant: 'destructive',
 confirmText: '삭제 실행'
 });
 if (isConfirmed) {
 try {
 await programAdminService.deleteProgram(name);
 toast('프로그램이 삭제되었습니다.', 'success');
 loadData();
 } catch (err: any) {
 toast(err.message || '삭제 중 오류가 발생했습니다.', 'error');
 }
 }
 };

 const columns: Column<Program>[] = [
 {
 header: '파일명',
 accessor: (item: Program) => (
 <div className="flex items-center gap-4 py-3">
 <div className="w-12 h-12 rounded-lg bg-slate-900 flex items-center justify-center text-white shadow-lg group-hover:scale-110 transition-transform">
 <Cpu size={20} />
 </div>
 <div className="text-left">
 <span className="font-bold tracking-tighter text-foreground block text-md uppercase leading-none">{item.progrmKoreanNm}</span>
 <span className="text-xs font-bold text-slate-600 tracking-[0.3em] mt-2 uppercase opacity-100 text-left">SYSTEM_MODULE</span>
 </div>
 </div>
 )
 },
 {
 header: '식별 파일명',
 accessor: (item: Program) => (
 <div className="flex justify-start">
 <div className="px-3 py-1 bg-slate-50 border border-slate-100 rounded-lg w-fit">
 <span className="text-xs font-bold text-primary tracking-tight font-mono">{item.progrmFileNm}</span>
 </div>
 </div>
 ),
 className: 'w-48'
 },
 {
 header: '엔드포인트(API/URL)',
 accessor: (item: Program) => (
 <div className="flex items-center gap-2 font-mono text-xs font-bold text-slate-600 tracking-tighter text-left">
 <LinkIcon size={12} className="text-primary opacity-40 shrink-0" />
 <span className="truncate">{item.url}</span>
 </div>
 ),
 className: 'w-64'
 },
 {
 header: '관리',
 className: 'text-right w-32',
 accessor: (item: Program) => (
 <div className="flex justify-end gap-2 pr-4">
 <Tooltip>
 <TooltipTrigger asChild>
 <Button variant="ghost" size="icon" className="h-10 w-10 rounded-lg bg-slate-50 border border-slate-100 hover:bg-primary hover:border-primary hover:text-white transition-all" onClick={() => handleOpenEdit(item)}>
 <Settings size={16} />
 </Button>
 </TooltipTrigger>
 <TooltipContent side="top" className="bg-slate-900 text-white border-none rounded-lg px-4 py-2 text-xs font-bold tracking-widest uppercase">
 프로그램 속성 및 엔드포인트 수정
 </TooltipContent>
 </Tooltip>

 <Tooltip>
 <TooltipTrigger asChild>
 <Button variant="ghost" size="icon" className="h-10 w-10 text-rose-500 bg-rose-50 border border-rose-100 hover:bg-rose-500 hover:text-white transition-all rounded-lg" onClick={() => handleDelete(item.progrmFileNm)}>
 <Trash2 size={16} />
 </Button>
 </TooltipTrigger>
 <TooltipContent side="top" className="bg-slate-900 text-white border-none rounded-lg px-4 py-2 text-xs font-bold tracking-widest uppercase text-rose-300">
 시스템 자산 영구 삭제
 </TooltipContent>
 </Tooltip>
 </div>
 )
 }
 ];

 return (
 <div className="space-y-12 pb-24 animate-in fade-in duration-1000">
 <PageHeader
 title="시스템 프로그램 미들웨어"
 breadcrumbs={[{ label: '시스템관리' }, { label: '프로그램 관리' }]}
 />

 <HubHeader
 title="프로그램"
 highlight="자산 관리"
 subtitle="시스템을 구성하는 모든 물리 프로그램 모듈 및 API 엔드포인트의 생명주기를 관리합니다."
 icon={Box}
 actions={
 <Tooltip>
 <TooltipTrigger asChild>
 <Button
 onClick={handleOpenCreate}
 size="lg"
 className="h-11 px-10 rounded-lg bg-slate-900 border-none text-white font-bold text-xs tracking-widest uppercase shadow-2xl hover:bg-primary transition-all hover:-translate-y-1 gap-3"
 >
 <Plus size={20} /> 신규 등록
 </Button>
 </TooltipTrigger>
 <TooltipContent side="bottom" className="bg-slate-900 text-white border-none rounded-lg px-4 py-2 text-xs font-bold tracking-widest uppercase">
 새로운 물리 프로그램 자산 정의
 </TooltipContent>
 </Tooltip>
 }
 />

 <HubMetricGrid>
 <HubMetricCard title="활성_프로그램_수" value={total} icon={Layers} color="primary" />
 <HubMetricCard title="시스템 무결성" value="정상" icon={ShieldCheck} color="emerald" status="확인됨" />
 <HubMetricCard title="서비스 가동시간" value="99.9%" icon={Zap} color="amber" />
 <HubMetricCard title="인벤토리 동기화" value="실시간" icon={RefreshCcw} color="indigo" />
 </HubMetricGrid>

 <HubSectionCard 
 title="소프트웨어 레포지토리" 
 description="현재 시스템에 등록되어 동작 중인 모든 소프트웨어 자산의 명세 및 메타데이터 정보입니다." 
 icon={SearchCode}
 >
 <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10 pb-10 border-b border-border/30">
 <div className="flex-1 max-w-2xl text-left">
 <div className="relative group/search">
 <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-muted-foreground opacity-30 group-focus-within/search:opacity-100 transition-opacity" size={20} />
 <Input
 placeholder="프로그램명 또는 파일명을 입력하여 검색.."
 value={currentSearchWrd}
 onChange={(e) => setCurrentSearchWrd(e.target.value)}
 onKeyDown={(e) => e.key === 'Enter' && loadData()}
 className="h-11 pl-16 pr-8 w-full bg-slate-50/50 border-none rounded-lg text-xs font-bold tracking-widest uppercase shadow-inner focus:ring-4 focus:ring-primary/10 transition-all"
 />
 </div>
 </div>
 <Button onClick={() => loadData()} size="lg" className="h-11 px-10 rounded-lg bg-slate-900 border-none text-white font-bold text-xs tracking-widest uppercase shadow-xl hover:bg-primary transition-all gap-2">
 <Search size={18} /> 검색
 </Button>
 </div>

 <div className="overflow-hidden">
 <StandardDataTable
 columns={columns}
 data={data}
 loading={loading}
 emptyMessage="시스템에 등록된 프로그램 자산이 존재하지 않습니다."
 className="border-none bg-transparent"
 />
 </div>
 </HubSectionCard>

 <StandardModal
 isOpen={isModalOpen}
 onClose={() => setIsOpen(false)}
 title={mode === 'create' ? '신규 프로그램 등록' : '프로그램 정보 수정'}
 maxWidth="2xl"
 >
 <ProgramForm 
 open={isModalOpen}
 onOpenChange={setIsOpen}
 data={mode === 'edit' ? (form.getValues() as any) : undefined}
 onSuccess={() => {
 loadData();
 setIsOpen(false);
 }}
 />
 </StandardModal>
 </div>
 );
}

