const INDENTATION_WIDTH = 24;

const dropAnimation: DropAnimation = {
    sideEffects: defaultDropAnimationSideEffects({
        styles: {
            active: {
                opacity: '0.5',
            },
        },
    }),
};

interface SortableDeptNodeProps {
    node: FlattenedDept;
    isSelected: boolean;
    onClick: () => void;
    isOverlay?: boolean;
}

const SortableDeptNode = ({ node, isSelected, onClick, isOverlay = false }: SortableDeptNodeProps) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging,
    } = useSortable({ id: node.orgnztId || '' });

    const style = {
        transform: isOverlay ? undefined : CSS.Translate.toString(transform),
        transition: isOverlay ? undefined : transition,
        paddingLeft: isOverlay ? 0 : `${node.depth * INDENTATION_WIDTH}px`,
    };

    return (
        <div
            ref={setNodeRef}
            style={style}
            className={cn(
                "group relative mb-1 outline-none",
                isDragging && !isOverlay && "opacity-30",
                isOverlay && "z-[9999] pointer-events-none"
            )}
        >
            {/* Hierarchy Line */}
            {node.depth > 0 && !isOverlay && (
                <>
                    <div className="absolute left-[11px] top-[-10px] bottom-1/2 w-px bg-slate-200" />
                    <div className="absolute left-[11px] top-1/2 w-3 h-px bg-slate-200" />
                </>
            )}

            <button
                type="button"
                {...attributes}
                {...listeners}
                onClick={onClick}
                className={cn(
                    "w-full flex items-center justify-between p-3 rounded-lg transition-all relative overflow-hidden",
                    "hover:bg-slate-50 border border-transparent",
                    isSelected && "bg-primary text-white shadow-lg shadow-primary/20 border-primary/20",
                    isOverlay && "bg-white shadow-2xl border-primary ring-4 ring-primary/5 scale-105"
                )}
            >
                <div className="flex items-center gap-3 truncate relative z-10 w-full">
                    <div className={cn(
                        "w-8 h-8 rounded-lg flex items-center justify-center transition-all shrink-0",
                        isSelected ? "bg-white/20 text-white" : "bg-indigo-50 text-indigo-500 group-hover:bg-primary/10 group-hover:text-primary"
                    )}>
                        <Building2 size={14} />
                    </div>
                    <div className="flex flex-col truncate items-start">
                        <span className={cn(
                            "text-xs font-bold truncate leading-tight tracking-tight",
                            isSelected ? "text-white" : "text-slate-900"
                        )}>
                            {node.orgnztNm}
                        </span>
                        <span className={cn(
                            "text-xs font-bold tracking-tighter opacity-60",
                            isSelected ? "text-white" : "text-slate-500"
                        )}>
                            {node.orgnztId}
                        </span>
                    </div>
                    {isSelected && (
                        <div className="ml-auto">
                            <div className="w-1.5 h-1.5 rounded-lg bg-white animate-pulse" />
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

type UserOrgTab = 'USERS' | 'DEPTS' | 'ABSENCES' | 'POLICIES';

export default function UserOrgHubClient({ 
  defaultTab = 'USERS',
  usersPromise,
  deptsPromise
}: { 
  defaultTab?: UserOrgTab;
  usersPromise: Promise<any>;
  deptsPromise: Promise<any>;
}) {
  const initialUsers = use(usersPromise);
  const initialDepts = use(deptsPromise);
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const confirm = useConfirm();
  const [isPending, startTransition] = React.useTransition();
  const [activeTab, setActiveTab] = useState<UserOrgTab>(defaultTab);
  const router = useRouter();
  const [isSaving, setIsSaving] = useState(false);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [selectedItemId, setSelectedItemId] = useState<string | number | null>(null);

  const [userPage, setUserPage] = useState(1);
  const [deptPage, setDeptPage] = useState(1);

  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [isDeptModalOpen, setIsDeptModalOpen] = useState(false);
  const [formMode, setFormMode] = useState<'create' | 'edit'>('create');

  // Bulk Actions State
  const [selectedBulkItems, setSelectedBulkItems] = useState<UserManage[]>([]);
  const [isBulkStatusModalOpen, setIsBulkStatusModalOpen] = useState(false);
  const [isBulkMoveModalOpen, setIsBulkMoveModalOpen] = useState(false);
  const [isBulkRoleModalOpen, setIsBulkRoleModalOpen] = useState(false);
  const [targetStatus, setTargetStatus] = useState('P');
  const [targetDeptId, setTargetDeptId] = useState('');
  const [targetRole, setTargetRole] = useState('USER');

  const { data: usersData, isLoading: isUsersLoading, error: usersError, refetch: refetchUsers } = useQuery({
    queryKey: ['admin-users', searchKeyword, userPage],
    queryFn: () => userAdminService.getUserList({ pageNo: userPage, searchKeyword }),
    enabled: activeTab === 'USERS' || activeTab === 'ABSENCES',
    initialData: (userPage === 1 && !searchKeyword) ? initialUsers : undefined
  });
  const users = useMemo(() => {
    const list = usersData?.list;
    return (Array.isArray(list) ? list.filter(Boolean) : []) as UserManage[];
  }, [usersData]);

  const { data: deptsData, isLoading: isDeptsLoading, error: deptsError, refetch: refetchDepts } = useQuery({
    queryKey: ['admin-depts', searchKeyword, deptPage],
    queryFn: () => deptAdminService.getDeptList({ pageNo: deptPage, searchKeyword }),
    enabled: activeTab === 'DEPTS',
    initialData: (deptPage === 1 && !searchKeyword) ? initialDepts : undefined
  });

  // D&D States for Depts
  const [flattenedDepts, setFlattenedDepts] = useState<FlattenedDept[]>([]);
  const [activeDeptId, setActiveDeptId] = useState<string | null>(null);
  const [hasDeptChanges, setHasDeptChanges] = useState(false);

  const departments = useMemo(() => {
    const list = deptsData?.list;
    return (Array.isArray(list) ? list.filter(Boolean) : []) as Department[];
  }, [deptsData]);

  useEffect(() => {
    if (activeTab === 'DEPTS' && departments.length > 0) {
        // Build tree and flatten it for D&D
        const tree = listToDeptTree(departments as any);
        setFlattenedDepts(flattenDeptTree(tree));
    }
  }, [departments, activeTab]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const onUserSubmit = async (values: UserFormValues) => {
    try {
      if (formMode === 'create') {
        await userAdminService.createUser(values as UserManage);
        toast('사용자가 성공적으로 등록되었습니다.', 'success');
      } else {
        await userAdminService.updateUser(selectedItemId as string, values as UserManage);
        toast('사용자 정보가 수정되었습니다.', 'success');
      }
      refetchUsers();
      setIsUserModalOpen(false);
    } catch (error) {
      toast('사용자 저장 중 오류가 발생했습니다.', 'error');
    }
  };

  const onDeptSubmit = async (values: DeptFormValues) => {
    try {
      if (formMode === 'create') {
        await deptAdminService.createDept(values as Department);
        toast('부서가 성공적으로 등록되었습니다.', 'success');
      } else {
        await deptAdminService.updateDept(selectedItemId as string, values as Department);
        toast('부서 정보가 수정되었습니다.', 'success');
      }
      refetchDepts();
      setIsDeptModalOpen(false);
    } catch (error) {
      toast('부서 저장 중 오류가 발생했습니다.', 'error');
    }
  };

  const handleDeleteUser = async () => {
    if (!selectedItemId) return;

    const ok = await confirm({
      title: '아이덴티티 삭제',
      message: '해당 사용자의 모든 접근 권한과 아이덴티티 프로필을 시스템에서 영구히 말소하시겠습니까?',
      variant: 'destructive',
      confirmText: 'REVOKE_IDENTITY'
    });

    if (ok) {
      try {
        await userAdminService.deleteUser(selectedItemId as string);
        toast('아이덴티티가 성공적으로 말소되었습니다.', 'success');
        setSelectedItemId(null);
        refetchUsers();
      } catch (error) {
        toast('말소 프로세스 중 오류가 발생했습니다.', 'error');
      }
    }
  };

  const handleBulkDelete = async (items: (UserManage | Department)[]) => {
    const userItems = items as UserManage[];
    const ok = await confirm({
      title: '일괄 신원 말소',
      message: `${userItems.length}명의 사용자를 시스템에서 영구히 삭제하시겠습니까?`,
      variant: 'destructive',
      confirmText: 'BULK_REVOKE'
    });
    if (ok) {
      const res = await bulkDeleteUsersAction(userItems.map(u => u.userId));
      if (res.success) {
        toast(res.message, 'success');
        refetchUsers();
      } else {
        toast(res.message, 'error');
      }
    }
  };

  const userBulkActions = [
    {
      label: '상태 변경',
      icon: <Activity size={16} />,
      onClick: (items: (UserManage | Department)[]) => {
        setSelectedBulkItems(items as UserManage[]);
        setIsBulkStatusModalOpen(true);
      }
    },
    {
      label: '부서 이동',
      icon: <Network size={16} />,
      onClick: (items: (UserManage | Department)[]) => {
        setSelectedBulkItems(items as UserManage[]);
        setIsBulkMoveModalOpen(true);
      }
    },
    {
      label: '권한 변경',
      icon: <ShieldCheck size={16} />,
      onClick: (items: (UserManage | Department)[]) => {
        setSelectedBulkItems(items as UserManage[]);
        setIsBulkRoleModalOpen(true);
      }
    },
    {
      label: '일괄 삭제',
      icon: <UserMinus size={16} />,
      variant: 'destructive' as const,
      onClick: handleBulkDelete
    }
  ];

  // --- Resilience Monitoring: Global Error Feedback ---
  React.useEffect(() => {
    if (usersError) {
      const msg = (usersError as any)?.response?.data?.message || '사용자 데이터를 불러오는데 오류가 발생했습니다.';
      toast(msg, 'error');
    }
  }, [usersError, toast]);

  React.useEffect(() => {
    if (deptsError) {
      toast('부서 데이터를 불러오는데 실패했습니다.', 'error');
    }
  }, [deptsError, toast]);

  const selectedItem = useMemo(() => {
    if (!selectedItemId) return null;
    if (activeTab === 'USERS' || activeTab === 'ABSENCES') return (users || []).find(u => u?.userId === selectedItemId);
    if (activeTab === 'DEPTS') return (departments || []).find(d => d?.orgnztId === selectedItemId);
    return null;
  }, [selectedItemId, activeTab, users, departments]);

  const userColumns: Column<UserManage>[] = [
    {
      header: '사용자 정보',
      accessor: (user) => (
        <div className="flex items-center gap-4 py-1">
          <div className={cn(
            "w-12 h-10 rounded-xl flex items-center justify-center font-black text-lg shadow-md transition-transform group-hover:rotate-6",
            selectedItemId === user?.esntlId ? "bg-white/20 text-white" : "bg-slate-100 text-slate-500"
          )}>
            {user?.userNm?.[0]}
          </div>
          <div className="space-y-0.5">
            <h4 className={cn("text-sm font-black tracking-tighter leading-none ", selectedItemId === user.esntlId ? "text-white" : "text-slate-900")}>
              {user.userNm}
            </h4>
            <p className={cn("text-[10px] font-bold tracking-tight opacity-60 ", selectedItemId === user.esntlId ? "text-white/80" : "text-slate-400")}>{user.userId}</p>
          </div>
        </div>
      )
    }
  ];

  const deptColumns: Column<Department>[] = [
    {
      header: '부서 정보',
      accessor: (dept) => (
        <div className="flex items-center gap-4 py-1">
          <div className={cn(
            "w-12 h-10 rounded-xl flex items-center justify-center shadow-md transition-transform group-hover:rotate-6",
            selectedItemId === dept.orgnztId ? "bg-white/20 text-white" : "bg-indigo-50 text-indigo-500"
          )}>
            <Building2 size={20} />
          </div>
          <div className="space-y-0.5">
            <h4 className={cn("text-sm font-black tracking-tighter leading-none ", selectedItemId === dept.orgnztId ? "text-white" : "text-foreground")}>
              {dept.orgnztNm}
            </h4>
            <p className={cn("text-[10px] font-bold tracking-tight opacity-60 ", selectedItemId === dept.orgnztId ? "text-white/80" : "text-slate-400")}>{dept.orgnztId}</p>
          </div>
        </div>
      )
    }
  ];

  return (
    <TooltipProvider delayDuration={0}>
      <div className="space-y-10 pb-24 animate-in fade-in duration-1000">
      <PageHeader
        title="조직 및 사용자 관리"
        breadcrumbs={[{ label: '사용자 관리' }, { label: '조직 통합 허브' }]}
      />

      <HubHeader
        title="사용자"
        highlight="관리 허브"
        subtitle="전사 인적 자원 및 조직 계층 구조를 통합 관리하는 컨트롤 센터입니다."
        icon={UserCog}
        actions={
          <div className="flex gap-3 p-1 items-center">
            <Tooltip>
              <TooltipTrigger asChild>
                <Button variant="ghost" size="lg" aria-label="개인화 환경 설정" className="h-10 w-12 rounded-xl bg-white border border-slate-200 text-slate-400 hover:text-primary hover:bg-primary/5 transition-all shadow-sm group active:scale-95">
                  <Settings size={20} className="group-hover:rotate-90 transition-transform duration-500" />
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="bg-slate-900 text-white border-none rounded-lg px-4 py-2 text-xs font-bold tracking-tight">
                환경 설정
              </TooltipContent>
            </Tooltip>

            <Tooltip>
              <TooltipTrigger asChild>
                <Button 
                  size="lg" 
                  className="h-10 px-8 rounded-xl bg-slate-900 border-none text-white font-black text-xs tracking-tight shadow-xl hover:bg-primary transition-all hover:-translate-y-1 gap-2 group"
                  onClick={() => {
                    setFormMode('create');
                    if (activeTab === 'DEPTS') {
                      setIsDeptModalOpen(true);
                    } else {
                      setIsUserModalOpen(true);
                    }
                  }}
                >
                  {activeTab === 'DEPTS' ? <LayoutGrid size={18} /> : <UserPlus size={18} />}
                  {activeTab === 'DEPTS' ? '부서 등록' : activeTab === 'ABSENCES' ? '부재 등록' : '사용자 등록'}
                </Button>
              </TooltipTrigger>
              <TooltipContent side="bottom" className="bg-slate-900 text-white border-none rounded-lg px-4 py-2 text-xs font-bold tracking-tight">
                {activeTab === 'DEPTS' ? '새로운 부서 추가' : '새로운 사용자 생성'}
              </TooltipContent>
            </Tooltip>
          </div>
        }
      />

      <div className={cn("grid grid-cols-12 gap-8 min-h-[800px] transition-opacity duration-500", isPending && "opacity-60 pointer-events-none")}>
        <div className="col-span-12 lg:col-span-3 space-y-6 flex flex-col h-full">
          <div className="rounded-2xl bg-white/40 backdrop-blur-md border border-white/60 shadow-xl p-3 flex flex-col gap-3">
            <NavButton icon={<Users size={20} />} subLabel="Menu_01" label="사용자" active={activeTab === 'USERS'} onClick={() => startTransition(() => { setActiveTab('USERS'); setSelectedItemId(null); })} />
            <NavButton icon={<Network size={20} />} subLabel="Menu_02" label="부서 관리" active={activeTab === 'DEPTS'} onClick={() => startTransition(() => { setActiveTab('DEPTS'); setSelectedItemId(null); })} />
            <NavButton icon={<UserMinus size={20} />} subLabel="Menu_03" label="부재 관리" active={activeTab === 'ABSENCES'} onClick={() => startTransition(() => { setActiveTab('ABSENCES'); setSelectedItemId(null); })} />
            <NavButton icon={<ShieldCheck size={20} />} subLabel="Menu_04" label="조직 정책" active={activeTab === 'POLICIES'} onClick={() => startTransition(() => { setActiveTab('POLICIES'); setSelectedItemId(null); })} />
          </div>

          <div className="mt-auto rounded-2xl bg-slate-900 text-white p-10 space-y-6 shadow-2xl relative overflow-hidden group border-none">
            <div className="absolute top-0 right-0 p-12 opacity-5 scale-150 rotate-12 transition-transform duration-1000 group-hover:rotate-6">
              <CloudLightning size={200} className="text-primary" />
            </div>
            <div className="relative z-10 space-y-4 text-center lg:text-left">
              <div className="w-12 h-10 bg-white/10 rounded-xl flex items-center justify-center mx-auto lg:mx-0 border border-white/5 shadow-inner group-hover:rotate-12 transition-transform">
                <Activity size={24} className="text-primary" />
              </div>
              <div className="space-y-2">
                <h4 className="text-xl font-black tracking-tighter leading-tight">사용자 통계</h4>
                <p className="text-[10px] text-white/60 font-bold tracking-tight leading-relaxed uppercase">Real-time status synced</p>
              </div>
            </div>
          </div>
        </div>

        <div className={cn("col-span-12 lg:col-span-4 h-full flex flex-col gap-6 transition-opacity duration-300", isPending && "opacity-50")}>
          <HubSectionCard
            title={activeTab === 'DEPTS' ? "조직 구조" : "사용자 목록"}
            description="실시간으로 동기화되는 조직 및 사용자 명세입니다."
            icon={activeTab === 'DEPTS' ? Network : Users}
          >
            <div className="space-y-6">
              <div className="flex items-center justify-between px-1 pt-1 border-b border-slate-100/50 pb-6">
                <div>
                  <span className="text-[10px] font-black text-slate-400 tracking-widest uppercase">실시간 데이터 동기화</span>
                </div>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="sm" aria-label="서버 데이터 동기화" onClick={() => queryClient.invalidateQueries()} className="h-10 rounded-xl px-5 text-[10px] font-black tracking-widest gap-2 hover:bg-slate-900 hover:text-white bg-slate-50 border border-slate-100 transition-all group shadow-sm uppercase">
                      <RefreshCcw size={14} className={cn("text-primary group-hover:text-white transition-colors", isUsersLoading || isDeptsLoading ? "animate-spin" : "group-hover:rotate-180")} /> Sync
                    </Button>
                  </TooltipTrigger>
