                  value={searchKeyword}
                  onChange={(e) => setSearchKeyword(e.target.value)}
                  suppressHydrationWarning
                />
              </div>

              <div className="overflow-y-auto pr-2 custom-scrollbar max-h-[600px]">
                <AnimatePresence mode="wait">
                  <motion.div
                    key={activeTab}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                    transition={{ duration: 0.5 }}
                    className="h-full"
                  >
                    {activeTab === 'DEPTS' ? (
                        <div className="space-y-1">
                            <DndContext
                                sensors={sensors}
                                collisionDetection={closestCenter}
                                measuring={{ droppable: { strategy: MeasuringStrategy.Always } }}
                                onDragStart={(e) => setActiveDeptId(e.active.id as string)}
                                onDragEnd={(event) => {
                                    const { active, over } = event;
                                    if (over && active.id !== over.id) {
                                        setFlattenedDepts((items) => {
                                            const oldIndex = items.findIndex(n => n.orgnztId === active.id);
                                            const newIndex = items.findIndex(n => n.orgnztId === over.id);
                                            const newItems = arrayMove(items, oldIndex, newIndex);

                                            const proj = getDeptProjection(items, active.id as string, over.id as string, 0, INDENTATION_WIDTH);
                                            if (proj) {
                                                const idx = newItems.findIndex(n => n.orgnztId === active.id);
                                                newItems[idx] = { ...newItems[idx], parentId: proj.parentId, depth: proj.depth };
                                            }
                                            return newItems;
                                        });
                                        setHasDeptChanges(true);
                                    }
                                    setActiveDeptId(null);
                                }}
                            >
                                <SortableContext items={flattenedDepts.map(n => n.orgnztId || '')} strategy={verticalListSortingStrategy}>
                                    <div className="space-y-1">
                                        {flattenedDepts.map((node) => (
                                            <SortableDeptNode
                                                key={node.orgnztId}
                                                node={node}
                                                isSelected={selectedItemId === node.orgnztId}
                                                onClick={() => setSelectedItemId(node.orgnztId || null)}
                                            />
                                        ))}
                                    </div>
                                </SortableContext>

                                {typeof document !== 'undefined' && createPortal(
                                    <DragOverlay dropAnimation={dropAnimation}>
                                        {activeDeptId ? (
                                            <SortableDeptNode
                                                node={flattenedDepts.find(n => n.orgnztId === activeDeptId)!}
                                                isSelected={false}
                                                onClick={() => {}}
                                                isOverlay
                                            />
                                        ) : null}
                                    </DragOverlay>,
                                    document.body
                                )}
                            </DndContext>
                            {hasDeptChanges && (
                              <div className="py-4">
                                <Button
                                  onClick={async () => {
                                    setIsSaving(true);
                                    try {
                                      const res = await saveDeptHierarchyAction(flattenedDepts);
                                      if (res.success) {
                                        toast(res.message, 'success');
                                        setHasDeptChanges(false);
                                        router.refresh();
                                      } else {
                                        toast(res.message, 'error');
                                      }
                                    } catch (err) {
                                      console.error(err);
                                      toast('구조 저장 중 오류 발생', 'error');
                                    } finally {
                                      setIsSaving(false);
                                    }
                                  }}
                                  disabled={isSaving}
                                  className="w-full h-11 rounded-xl bg-emerald-500 text-white font-black text-xs tracking-widest shadow-lg hover:bg-emerald-600 transition-all gap-2 uppercase"
                                >
                                  {isSaving ? <RefreshCcw size={14} className="animate-spin" /> : <Save size={14} />} 
                                  Save Structure
                                </Button>
                              </div>
                            )}
                            {flattenedDepts.length === 0 && !isDeptsLoading && (
                                <div className="py-20 text-center space-y-4">
                                    <div className="w-16 h-10 rounded-xl bg-slate-50 flex items-center justify-center mx-auto text-slate-200 border border-slate-100 shadow-inner">
                                        <SearchSlash size={32} />
                                    </div>
                                    <p className="text-xs font-bold tracking-tight text-slate-400 uppercase tracking-widest">No nodes found</p>
                                </div>
                            )}
                        </div>
                    ) : (
                        <StandardDataTable<UserManage>
                            columns={userColumns as Column<UserManage>[]}
                            data={users}
                            loading={isUsersLoading}
                            error={usersError as Error | null}
                            onRetry={() => refetchUsers()}
                            onRowClick={(item) => {
                                if (item.userId) setSelectedItemId(item.userId);
                            }}
                            keyField="userId"
                            emptyMessage="데이터가 존재하지 않습니다."
                            isPremium={true}
                            enableSelection={true}
                            bulkActions={userBulkActions}
                            className="border-none shadow-none bg-transparent"
                            pagination={{
                                currentPage: userPage,
                                totalPages: usersData?.totalPage || 1,
                                onPageChange: (p) => setUserPage(p)
                            }}
                        />
                    )}
                  </motion.div>
                </AnimatePresence>
              </div>
            </div>
          </HubSectionCard>
        </div>

        <div className="col-span-12 lg:col-span-5 h-full">
          <AnimatePresence mode="wait">
            {selectedItemId ? (
              <motion.div
                key={selectedItemId}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="h-full flex flex-col gap-6"
              >
                <div className="rounded-2xl bg-white/70 backdrop-blur-xl border border-white shadow-2xl h-full p-10 space-y-10 flex flex-col relative overflow-hidden ring-1 ring-black/5">
                  <div className="absolute top-0 right-0 p-12 opacity-[0.03] scale-150 rotate-12 transition-transform duration-1000">
                    <SearchCode size={250} className="text-primary" />
                  </div>

                  <div className="flex items-start justify-between border-b border-slate-100/50 pb-10 relative z-10">
                    <div className="flex items-center gap-8">
                      <div className="w-24 h-20 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-4xl text-white shadow-2xl rotate-2 group hover:rotate-6 transition-transform">
                        <span className="text-primary">
                          {activeTab === 'DEPTS' ? (selectedItem as Department)?.orgnztNm?.[0] : (selectedItem as UserManage)?.userNm?.[0]}
                        </span>
