  const handleRefresh = async () => {
    setLoading(true);
    try {
      const res = await manualAdminService.getManualList({ keyword: searchKeyword });
      setManuals(res.list);
      setTotalCount(res.total);
    } catch (error) {
      toast.error('매뉴얼 목록을 불러오지 못했습니다.');
