  };

  const handleOpenEdit = (manual: ManualDto) => {
    setMode('edit');
    form.reset({ 
      onlineMnlId: manual.onlineMnlId || '',
      onlineMnlNm: manual.onlineMnlNm || '', 
      onlineMnlDc: manual.onlineMnlDc || '', 
      onlineMnlDf: manual.onlineMnlDf || '' 
