      accessor: (item) => <span className="text-xs font-bold text-slate-500 font-mono tracking-tighter truncate max-w-xs block">{item.cntcUrl}</span>
    },
    {
      header: '상태',
      accessor: (item) => (
        <button 
          onClick={(e) => { e.stopPropagation(); toggleStatus(item); }}
          className={`inline-flex items-center px-3 py-1 rounded-lg text-[10px] font-black tracking-widest uppercase transition-all ${item.cntntsUseAt === 'Y'
            ? 'bg-emerald-500/10 text-emerald-600 border border-emerald-500/20'
            : 'bg-slate-100 text-slate-400 border border-slate-200'
