import React, { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import {
    Search,
    Command,
    FileText,
    Users,
    Settings,
    LayoutDashboard,
    ArrowRight,
    X
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { menuAdminService } from '@/services/foundation/system/MenuAdminService';

interface SearchResult {
    id: string;
    category: 'Menu' | 'Content' | 'User';
    title: string;
    url: string;
    description?: string;
    icon: React.ReactNode;
}

// 카테고리별 아이콘 매핑
const categoryIcons = {
    Menu: <Settings size={14} />,
    Content: <FileText size={14} />,
    User: <Users size={14} />,
};

export function CommandPalette() {
    const router = useRouter();
    const [isOpen, setIsOpen] = useState(false);
    const [query, setQuery] = useState('');
    const [selectedIndex, setSelectedIndex] = useState(0);
    const [results, setResults] = useState<SearchResult[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // 메뉴 데이터 로드
    useEffect(() => {
        if (!isOpen) return;

        const loadMenus = async () => {
            setIsLoading(true);
            try {
                const menus = await menuAdminService.getAllMenus();

                const searchResults: SearchResult[] = menus
                    .filter(menu => menu.modernRoute && menu.modernRoute !== '#' && menu.menuNo <= 9999999)
                    .map(menu => ({
                        id: String(menu.menuNo),
                        category: 'Menu' as const,
                        title: menu.menuNm,
                        url: menu.modernRoute!,
                        description: menu.menuDc || undefined,
                        icon: getMenuIcon(menu.modernRoute!),
                    }));

                setResults(searchResults);
            } catch (error) {
                console.error('Failed to load menus:', error);
                setResults([]);
            } finally {
                setIsLoading(false);
            }
        };

        loadMenus();
    }, [isOpen]);

    // 필터링된 결과
    const filteredResults = results.filter(item =>
        (item.title || '').toLowerCase().includes(query.toLowerCase()) ||
        (item.category || '').toLowerCase().includes(query.toLowerCase()) ||
        (item.description && item.description.toLowerCase().includes(query.toLowerCase()))
    );

    const handleOpen = useCallback(() => setIsOpen(true), []);
    const handleClose = useCallback(() => {
        setIsOpen(false);
        setQuery('');
        setSelectedIndex(0);
    }, []);

    useEffect(() => {
        const down = (e: KeyboardEvent) => {
            if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                setIsOpen((open) => !open);
            }
            if (e.key === 'Escape') handleClose();
        };

        document.addEventListener('keydown', down);
        return () => document.removeEventListener('keydown', down);
    }, [handleClose]);

    const onSelect = (url: string) => {
        router.push(url);
        handleClose();
    };

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[15vh] px-4 md:px-0 bg-black/80 animate-in fade-in duration-300">
            <div className="w-full max-w-2xl bg-white dark:bg-slate-900 border shadow-2xl rounded-lg overflow-hidden animate-in zoom-in-95 duration-200">
                {/* 검색 입력 영역 */}
                <div className="flex items-center p-6 border-b gap-4">
                    <Search className="text-muted-foreground" size={20} />
                    <input
                        autoFocus
                        className="flex-1 bg-transparent border-none outline-none text-lg font-bold placeholder:text-muted-foreground/50 text-foreground"
                        placeholder="무엇을 찾으시나요? (메뉴, 사용자, 게시글...)"
                        value={query}
                        onChange={(e) => {
                            setQuery(e.target.value);
                            setSelectedIndex(0);
                        }}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' && filteredResults[selectedIndex]) {
                                onSelect(filteredResults[selectedIndex].url);
                            }
                            if (e.key === 'ArrowDown') setSelectedIndex((i) => Math.min(filteredResults.length - 1, i + 1));
                            if (e.key === 'ArrowUp') setSelectedIndex((i) => Math.max(0, i - 1));
                        }}
                    />
                    {isLoading && (
                        <div className="text-xs text-muted-foreground animate-pulse">로딩 중...</div>
                    )}
                    <div className="flex items-center gap-1 bg-muted px-2 py-1 rounded-md">
                        <span className="text-xs font-bold text-muted-foreground">ESC</span>
                    </div>
                    <button onClick={handleClose} className="p-1 hover:bg-muted rounded-lg text-muted-foreground">
                        <X size={18} />
                    </button>
                </div>

                {/* 결과 영역 */}
                <div className="max-h-[50vh] overflow-y-auto p-4 space-y-4 custom-scrollbar">
                    {isLoading ? (
                        <div className="p-20 flex flex-col items-center justify-center text-center space-y-4">
                            <div className="p-6 rounded-lg bg-muted animate-spin">
                                <Search size={40} className="text-muted-foreground/30" />
                            </div>
                            <div>
                                <p className="text-lg font-bold text-foreground">메뉴를 불러오는 중..</p>
                                <p className="text-sm text-muted-foreground font-bold">잠시만 기다려 주세요.</p>
                            </div>
                        </div>
                    ) : filteredResults.length > 0 ? (
                        <div className="space-y-1">
                            {['Menu', 'Content', 'User'].map((cat) => {
                                const catResults = filteredResults.filter(r => r.category === cat);
                                if (catResults.length === 0) return null;
                                return (
                                    <div key={cat} className="mb-4">
                                        <h3 className="text-xs font-bold text-muted-foreground tracking-tight px-4 mb-2">{cat}</h3>
                                        <div className="space-y-1">
                                            {catResults.map((result) => {
                                                const globalIdx = filteredResults.indexOf(result);
                                                return (
                                                    <button
                                                        key={result.id}
                                                        className={cn(
                                                            "w-full group p-4 rounded-lg flex items-center justify-between transition-all outline-none border-2 border-transparent",
                                                            globalIdx === selectedIndex ? "bg-primary text-primary-foreground shadow-lg scale-[1.01]" : "hover:bg-muted text-foreground"
                                                        )}
                                                        onClick={() => onSelect(result.url)}
                                                        onMouseEnter={() => setSelectedIndex(globalIdx)}
                                                    >
                                                        <div className="flex items-center gap-4 text-left">
                                                            <div className={cn(
                                                                "w-10 h-10 rounded-lg flex items-center justify-center transition-all",
                                                                globalIdx === selectedIndex ? "bg-white/20 border-white/10 shadow-inner" : "bg-primary/5 text-primary border border-primary/10"
                                                            )}>
                                                                {result.icon}
                                                            </div>
                                                            <div>
                                                                <p className="text-sm font-bold tracking-tight">{result.title}</p>
                                                                {result.description && (
                                                                    <p className={cn(
                                                                        "text-xs font-bold line-clamp-1",
                                                                        globalIdx === selectedIndex ? "text-primary-foreground/70" : "text-muted-foreground/60"
                                                                    )}>
                                                                        {result.description}
                                                                    </p>
                                                                )}
                                                            </div>
                                                        </div>
                                                        <ArrowRight className={cn(
                                                            "transition-all duration-300",
                                                            globalIdx === selectedIndex ? "opacity-100 translate-x-0" : "opacity-0 -translate-x-2"
                                                        )} size={16} />
                                                    </button>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="p-20 flex flex-col items-center justify-center text-center space-y-4">
                            <div className="p-6 rounded-lg bg-muted animate-bounce">
                                <Search size={40} className="text-muted-foreground/30" />
