};

const NavItem = ({ item, depth = 0 }: { item: MenuInfo; depth?: number }) => {
  const pathname = usePathname();
  const { setSidebarOpen } = useLayout();
  const hasChildren = item.children && item.children.length > 0;
  const [isOpen, setIsOpen] = useState(false);
  const [isMounted, setIsMounted] = useState(false);
  const Icon = ICON_MAP[item.menuNm] || ICON_MAP['기본'];

  // URL normalization and mapping
  const href = useMemo(() => {
    const rawUrl = item.modernRoute || item.chkURL;
    if (!rawUrl || rawUrl === '#') return '#';

    // Ensure leading slash for internal links
    const formatted = rawUrl.startsWith('/') ? rawUrl : `/${rawUrl}`;

    return formatted;
  }, [item.modernRoute, item.chkURL]);

  const isActive = useMemo(() => {
    if (href !== '#' && String(pathname).startsWith(String(href))) return true;
    if (hasChildren && item.children) {
      return item.children.some(child => {
        const childHref = child.modernRoute || child.chkURL;
        return childHref && String(pathname).startsWith(String(childHref).startsWith('/') ? String(childHref) : `/${String(childHref)}`);
      });
    }
    return false;
  }, [pathname, href, hasChildren, item.children]);

  useEffect(() => {
    setIsMounted(true);
    if (isActive && hasChildren) {
      setIsOpen(true);
    }
  }, [isActive, hasChildren]);

  const { user } = useAuth();
  const isAdmin = user?.role === 'ROLE_ADMIN' || user?.userSe === 'USR';

  // Backend filters menus based on roles, so we don't need hardcoded keyword restrictions.
  const isRestricted = false;

  const handleLinkClick = (e: React.MouseEvent) => {
    if (isRestricted) {
      e.preventDefault();
      return;
    }
    setSidebarOpen(false);
    if (href === '#') {
      if (hasChildren) {
        e.preventDefault();
        setIsOpen(!isOpen);
      }
    } else if (href.endsWith('.do')) {
      console.warn(`[Sidebar] Legacy URL detected: ${href}`);
    }
  };

  const navContent = (
    <div className={cn(
      "flex items-center justify-between gap-3 px-3 py-2.5 text-[13px] font-bold tracking-tight rounded-[var(--radius-hub-item)] transition-all duration-300 w-full group focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary relative hover:translate-x-1 hover:bg-slate-900 hover:text-white",
      isActive
        ? "bg-slate-900 text-white shadow-xl"
        : "text-slate-500 hover:bg-slate-900 hover:text-white",
      isRestricted && "opacity-40 cursor-not-allowed grayscale",
      depth === 1 && "pl-10",
      depth === 2 && "pl-14",
      depth >= 3 && "pl-16",
      depth > 0 && "font-bold"
    )}>
      <div className="flex items-center gap-3">
        {Icon && depth === 0 && (
          <Icon
            size={18}
            className={cn(
              "transition-transform duration-200 group-hover:scale-110",
              isActive ? "text-primary" : "text-slate-600"
            )}
          />
        )}
        {depth > 0 && (
          <div className={cn(
            "absolute left-4 w-1.5 h-1.5 rounded-lg border border-current opacity-80 transition-transform duration-200",
            isActive ? "bg-primary border-primary scale-110 opacity-100" : "group-hover:scale-110"
          )} 
          style={{ left: `${(depth * 12) + 12}px` }}
          />
        )}
        <span className={cn("truncate", depth > 0 && "text-[13px]")}>{item.menuNm}</span>
      </div>
      {hasChildren && (
        <motion.div
          animate={{ rotate: isOpen ? 180 : 0 }}
          transition={{ duration: 0.2 }}
          className="opacity-100"
          onClick={(e) => {
            if (href !== '#') {
              e.preventDefault();
              e.stopPropagation();
              setIsOpen(!isOpen);
            }
          }}
        >
          <ChevronDown size={14} />
        </motion.div>
      )}
    </div>
  );

  if (!isMounted) return null;

  return (
    <div className="w-full relative">
      <Link
        href={href}
        className="block w-full focus-visible:outline-none"
        onClick={handleLinkClick}
      >
        {navContent}
      </Link>

      <AnimatePresence initial={false}>
        {hasChildren && isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: [0.23, 1, 0.32, 1] }}
            className="overflow-hidden"
          >
            <div className={cn(
              "mt-1 space-y-0.5 relative",
              depth === 0 && "ml-5 border-l border-border/40"
            )}>
              {item.children?.map((child, idx) => (
                <NavItem key={child.menuNo || `child-${idx}`} item={child} depth={depth + 1} />
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

