                                : "hover:bg-primary/5 text-foreground"
                            )}
                            onClick={() => handleSelect(item)}
                            onMouseEnter={() => setSelectedIndex(globalIndex)}
                          >
                            <div className="flex items-center gap-5">
                              <div className={cn(
