                        )}
                    </SafeResponsiveContainer>
                )}
            </div>
        </div>
    );
}

function CustomTooltip({ active, payload, label }: { active?: boolean; payload?: unknown[]; label?: string }) {
    if (active && payload && (payload as unknown[]).length) {
        return (
            <div className="bg-background/95 backdrop-blur-sm border shadow-2xl rounded-lg p-3 min-w-[120px]">
                <p className="text-xs font-bold text-muted-foreground mb-1 tracking-tighter">{label}</p>
                <div className="space-y-1">
                    {(payload as any[] || []).map((p, idx) => (
                        <div key={`tooltip-item-${idx}`} className="flex items-center justify-between gap-4">
                            <div className="flex items-center gap-2">
                                <div className="w-2 h-2 rounded-lg" style={{ backgroundColor: p.color || p.fill }} />
                                <span className="text-sm font-bold text-foreground">{p.name}</span>
                            </div>
                            <span className="text-sm font-bold text-primary">{p.value?.toLocaleString() || 0}</span>
                        </div>
                    ))}
                </div>
            </div>
        );
    }
    return null;
}

import React, { useState, useMemo, memo, useCallback } from 'react';
import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { List, Search, RefreshCw, ChevronLeft, ChevronRight, AlertCircle } from "lucide-react";
import { Input } from "@/components/ui/input";
import { motion, AnimatePresence } from "framer-motion";

export interface Column<T> {
  header: string;
  accessor: keyof T | ((item: T, index?: number) => React.ReactNode);
  className?: string;
}

export interface BulkAction<T> {
  label: string;
  icon?: React.ReactNode;
  variant?: 'default' | 'destructive' | 'outline';
  onClick: (selectedItems: T[]) => void;
}

export interface StandardDataTableProps<T> {
  columns: Column<T>[];
  data: T[];
  loading?: boolean;
  onRowClick?: (item: T) => void;
  emptyMessage?: string;
  enableSelection?: boolean;
  bulkActions?: BulkAction<T>[];
  keyField?: keyof T;
  className?: string;
  isPremium?: boolean;
  error?: Error | null;
  onRetry?: () => void;
  pagination?: {
    currentPage: number;
    totalPages: number;
    onPageChange: (page: number) => void;
  };
  search?: {
    placeholder?: string;
    onSearch: (keyword: string) => void;
  };
  stickyHeader?: boolean;
  rowTestId?: string;
}

const DataRow = memo(function DataRow({
  item,
  columns,
  isSelected,
  index,
  enableSelection,
  onToggle,
  onRowClick,
  rowTestId
}: {
  item: any;
  columns: Column<any>[];
  isSelected: boolean;
  index: number;
  enableSelection: boolean;
  onToggle: () => void;
  onRowClick?: (item: any) => void;
  rowTestId?: string;
}) {
  if (!item) return null;

  return (
    <tr
      role="button"
      tabIndex={0}
      data-testid={rowTestId}
      onKeyDown={(e) => { if((e.key === 'Enter' || e.key === ' ') && onRowClick) { e.preventDefault(); onRowClick(item); } }}
      className={cn(
        "group transition-all duration-300 outline-none focus-within:bg-muted/30 focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset",
        isSelected ? "bg-primary/5" : "hover:bg-muted/40",
        onRowClick && "cursor-pointer"
      )}
      onClick={() => onRowClick?.(item)}
    >
      {enableSelection && (
        <td className="px-6 py-4 text-center" onClick={(e) => e.stopPropagation()}>
          <Checkbox
            checked={isSelected}
            onCheckedChange={onToggle}
            aria-label="항목 선택"
          />
        </td>
      )}
      {columns.map((column, colIdx) => (
        <td
          key={`row-cell-${colIdx}`}
          className={cn(
            "px-6 py-5 text-sm font-medium text-foreground/80 tracking-tight transition-colors group-hover:text-foreground",
            column.className
          )}
        >
          <div className="outline-none">
            {typeof column.accessor === 'function'
              ? (column.accessor as any)(item, index)
              : item?.[column.accessor as any]}
          </div>
        </td>
      ))}
    </tr>
  );
});

const MobileCard = memo(function MobileCard({
  item,
  columns,
  isSelected,
  index,
  enableSelection,
  onToggle,
  onRowClick
}: any) {
