 */
export function FormField({
  label,
  htmlFor,
  error,
  children,
  required,
  description
}: {
  label: string;
  htmlFor?: string;
  error?: string;
  children: React.ReactNode;
  required?: boolean;
  description?: string;
}) {
  return (
    <div className="space-y-1.5 p-0.5">
      <label htmlFor={htmlFor} className="text-xs font-bold text-slate-800 flex items-center gap-1.5 ml-1 uppercase tracking-tight">
        {label}
        {required ? <span className="text-rose-500 font-bold text-xs" aria-hidden="true">*</span> : null}
      </label>
      <div className="relative">
        {children}
      </div>
      {error ? <p id={`${htmlFor}-error`} role="alert" className="text-xs font-bold text-rose-600 px-1 mt-1">{error}</p> : null}
      {description ? <p id={`${htmlFor}-description`} className="text-xs font-bold text-slate-500 px-1 mt-1 leading-relaxed">{description}</p> : null}
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
 X,
 ChevronRight,
 ChevronLeft,
 Sparkles,
 Command,
 Layout,
 Bell,
 User,
 CheckCircle2
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';

interface TourStep {
 title: string;
 description: string;
 icon: React.ReactNode;
}

export function StandardOnboardingTour() {
 const [isOpen, setIsOpen] = useState(false);
 const [currentStep, setCurrentStep] = useState(0);
 const [mounted, setMounted] = useState(false);

 useEffect(() => {
 setMounted(true);
 if (typeof window !== 'undefined') {
 const hasSeenTour = localStorage.getItem('egov_tour_completed');
 if (!hasSeenTour) {
 const timer = setTimeout(() => setIsOpen(true), 1500);
 return () => clearTimeout(timer);
 }
 }
 }, []);

 const handleComplete = () => {
 if (typeof window !== 'undefined') {
 localStorage.setItem('egov_tour_completed', 'true');
 }
 setIsOpen(false);
 };

 const nextStep = () => {
 if (currentStep < steps.length - 1) {
 setCurrentStep(prev => prev + 1);
 } else {
 handleComplete();
 }
 };

 const prevStep = () => {
 if (currentStep > 0) {
 setCurrentStep(prev => prev - 1);
 }
 };

 const steps: TourStep[] = [
 {
 title: "eGov 5.0 플랫폼에 오신 것을 환영합니다",
 description: "차세대 공공 정보 시스템을 주도하는 새로운 관리 프레임워크입니다. 빠르고 직관적인 업무 환경을 경험해 보세요.",
 icon: <Sparkles className="text-primary" size={32} />
 },
 {
 title: "스마트 내비게이션",
 description: "왼쪽 사이드바를 통해 모든 업무 모듈에 빠르게 접근할 수 있습니다. 계층형 메뉴와 현대적인 아이콘으로 원하는 메뉴를 쉽게 찾아보세요.",
 icon: <Layout className="text-blue-500" size={32} />
 },
 {
 title: "글로벌 커맨드 센터 (Ctrl+K)",
 description: "마우스 클릭 없이 키보드만으로 어디든 이동하세요. 단축키 Ctrl+K를 눌러 메뉴 검색, 사용자 찾기, 빠른 액션을 실행할 수 있습니다.",
 icon: <Command className="text-purple-500" size={32} />
 },
 {
 title: "실시간 지능형 알림",
 description: "상단 종 모양 아이콘을 통해 실시간 업무 알림을 받아보세요. 새로운 결재 요청이나 공지사항이 등록되면 즉시 알려드립니다.",
 icon: <Bell className="text-orange-500" size={32} />
 }
 ];

 if (!mounted || !isOpen) return null;

 return (
 <div
 className="fixed inset-0 z-[10000] flex items-center justify-center p-6 bg-slate-950/20 backdrop-blur-sm animate-in fade-in duration-500"
 role="alertdialog"
 aria-modal="true"
 aria-labelledby="tour-title"
 aria-describedby="tour-description"
 >
 <div className="relative max-w-lg w-full bg-background/80 backdrop-blur-2xl border-2 border-primary/10 rounded-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-500 ring-1 ring-white/20">
 {/* Progress Bar */}
 <div className="absolute top-0 left-0 w-full h-1.5 flex gap-1 px-1 pt-1" aria-hidden="true">
 {steps.map((_, idx) => (
 <div
 key={idx}
 className={cn(
 "h-full rounded-lg transition-all duration-500 flex-1",
 idx <= currentStep ? "bg-primary" : "bg-muted/30"
 )}
 />
 ))}
 </div>

 <button
 onClick={handleComplete}
 className="absolute top-6 right-6 p-2 hover:bg-muted rounded-lg transition-colors z-20 text-muted-foreground"
 aria-label="가이드 닫기"
 >
 <X size={20} />
 </button>

 <div className="p-10 pt-16 text-center space-y-8 relative z-10" aria-live="polite">
 <div className="w-20 h-11 bg-muted/50 rounded-lg flex items-center justify-center mx-auto shadow-inner animate-in slide-in-from-bottom-2 duration-700" aria-hidden="true">
 {steps[currentStep].icon}
 </div>

 <div className="space-y-3 min-h-[140px] animate-in fade-in slide-in-from-bottom-2 duration-700">
 <h2 id="tour-title" className="text-3xl font-bold tracking-tight text-foreground">
 {steps[currentStep].title}
 </h2>
 <p id="tour-description" className="text-base text-muted-foreground font-medium leading-relaxed">
 {steps[currentStep].description}
 </p>
 </div>

 <div className="flex items-center justify-between pt-4">
 <Button
 variant="ghost"
 onClick={prevStep}
 className={cn(
 "rounded-lg font-bold h-12 px-6 gap-2",
 currentStep === 0 && "invisible"
 )}
 aria-label="이전 단계로 이동"
 >
 <ChevronLeft size={18} /> 이전
 </Button>

 <div className="flex gap-2">
 {currentStep < steps.length - 1 ? (
 <>
 <Button variant="ghost" onClick={handleComplete} className="rounded-lg font-bold h-12 px-6 text-muted-foreground" aria-label="가이드 건너뛰기">
 건너뛰기
 </Button>
 <Button onClick={nextStep} className="rounded-lg font-bold h-12 px-8 gap-2 shadow-xl shadow-primary/20 hover:scale-105 transition-all" aria-label="다음 단계로 이동">
 다음 가이드 <ChevronRight size={18} />
 </Button>
 </>
 ) : (
 <Button onClick={handleComplete} className="rounded-lg font-bold h-12 px-10 gap-2 shadow-xl shadow-primary/20 bg-primary hover:bg-primary/90 text-white hover:scale-105 transition-all" aria-label="가이드 완료 및 시작하기">
 시작하기 <CheckCircle2 size={18} />
 </Button>
 )}
 </div>
 </div>
 </div>

 <div className="bg-muted/20 px-10 py-4 border-t border-primary/5 text-center">
 <p className="text-xs font-bold text-muted-foreground/40 tracking-[0.3em]">
 Step {currentStep + 1} of {steps.length} User Onboarding Experience
 </p>
 </div>
 </div>
 </div>
 );
}

import React, { useState } from 'react';
import { Search, RotateCcw, Calendar as CalendarIcon, ChevronDown, ChevronUp, SlidersHorizontal } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar } from '@/components/ui/calendar';
import { format } from 'date-fns';
import { ko } from 'date-fns/locale';

export interface FilterField {
  name: string;
  label: string;
  type: 'text' | 'select' | 'date' | 'daterange';
  placeholder?: string;
  options?: { label: string; value: string }[];
}

interface StandardSearchFilterProps {
  fields: FilterField[];
  onSearch: (values: Record<string, any>) => void;
  onReset?: () => void;
  className?: string;
  isPremium?: boolean;
}

export function SmartSearchPanel({ fields, onSearch, onReset, className, isPremium = true }: StandardSearchFilterProps) {
  const [values, setValues] = useState<Record<string, any>>({});
  const [isExpanded, setIsExpanded] = useState(true);

  const handleValueChange = (name: string, value: any) => {
    setValues(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSearch(values);
  };

  const handleReset = () => {
    setValues({});
    onReset?.();
  };

  return (
    <div className={cn(
      "border-2 border-border/60 bg-card shadow-sm mb-8 transition-all group overflow-hidden", 
      isPremium ? "p-8 rounded-lg" : "p-5 rounded-lg",
      className
    )}>
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-primary/10 rounded-lg text-primary flex items-center justify-center transition-transform group-hover:rotate-6 duration-500 shadow-sm border border-primary/5">
              <SlidersHorizontal size={20} />
            </div>
            <div>
              <h3 className="text-base font-bold text-foreground tracking-tighter leading-none uppercase">검색 조건 설정</h3>
              <p className="text-xs font-bold text-slate-700 mt-1.5 uppercase tracking-widest">고급 필터링 시스템</p>
            </div>
          </div>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => setIsExpanded(!isExpanded)}
            className="rounded-lg font-bold h-10 px-4 gap-2 hover:bg-muted transition-all text-muted-foreground"
          >
            {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            <span className="text-xs tracking-widest font-bold uppercase">필터 {isExpanded ? '접기' : '펼치기'}</span>
          </Button>
        </div>

        {isExpanded && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-8 gap-y-6 animate-in fade-in slide-in-from-top-4 duration-500">
            {fields.map((field) => (
              <div key={field.name} className="space-y-2 group/field">
                <label className="text-xs font-bold text-slate-700 uppercase tracking-[0.2em] ml-1 group-focus-within/field:text-primary transition-colors">
                  {field.label.toUpperCase()}
                </label>

                {field.type === 'select' ? (
                  <Select
                    value={values[field.name] === '' ? '__ALL__' : (values[field.name] || '')}
                    onValueChange={(v) => handleValueChange(field.name, v === '__ALL__' ? '' : v)}
                  >
                    <SelectTrigger className="h-12 rounded-lg border border-input bg-background focus:ring-4 focus:ring-primary/10 hover:border-primary/50 transition-all font-bold text-sm ring-offset-background shadow-sm">
                      <SelectValue placeholder={field.placeholder || "전체"} />
                    </SelectTrigger>
                    <SelectContent className="rounded-lg shadow-2xl border-border bg-background p-1">
                      {field.options?.map(opt => (
                        <SelectItem
                          key={opt.value || '__ALL__'}
                          value={opt.value === '' ? '__ALL__' : opt.value}
                          className="text-sm font-bold rounded-lg m-1 cursor-pointer transition-colors"
                        >
                          {opt.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : field.type === 'daterange' ? (
                  <Popover>
                    <PopoverTrigger asChild>
                      <Button
                        variant="outline"
                        className={cn(
                          "w-full h-12 justify-start text-left font-bold text-sm rounded-lg border border-input bg-background transition-all hover:border-primary/50 shadow-sm",
                          !values[field.name] && "text-muted-foreground/50"
                        )}
                      >
                        <CalendarIcon className="mr-3 h-4 w-4 opacity-50 text-primary" />
                        {values[field.name]?.from ? (
                          values[field.name].to ? (
                            <span className="tracking-tight">
                              {format(values[field.name].from, "LLL dd", { locale: ko })} -{" "}
                              {format(values[field.name].to, "LLL dd", { locale: ko })}
                            </span>
                          ) : (
                            <span className="tracking-tight">{format(values[field.name].from, "LLL dd", { locale: ko })}</span>
                          )
                        ) : (
                          <span className="tracking-tight uppercase text-xs font-bold tracking-widest">날짜 범위 선택</span>
                        )}
                      </Button>
                    </PopoverTrigger>
                    <PopoverContent className="w-auto p-2 rounded-lg border-2 border-border shadow-2xl overflow-hidden bg-background" align="start">
                      <Calendar
                        initialFocus
                        mode="range"
                        defaultMonth={values[field.name]?.from}
                        selected={values[field.name]}
                        onSelect={(v) => handleValueChange(field.name, v)}
                        numberOfMonths={2}
                        locale={ko}
                        className="p-3"
                      />
                    </PopoverContent>
                  </Popover>
                ) : field.type === 'date' ? (
                  <Input
                    type="date"
                    value={values[field.name] || ''}
                    onChange={(e) => handleValueChange(field.name, e.target.value)}
                    className="h-12 rounded-lg border border-input bg-background font-bold text-sm ring-offset-background transition-all hover:border-primary/50 focus-visible:ring-4 focus-visible:ring-primary/10 shadow-sm"
                  />
                ) : (
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <Input
                      placeholder={field.placeholder?.toUpperCase()}
                      value={values[field.name] || ''}
                      onChange={(e) => handleValueChange(field.name, e.target.value)}
                      className="h-12 pl-11 rounded-lg border border-input bg-background font-bold text-sm ring-offset-background transition-all hover:border-primary/50 focus-visible:ring-4 focus-visible:ring-primary/10 shadow-sm placeholder:font-bold placeholder:text-xs placeholder:tracking-widest"
                    />
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        <div className="flex justify-end items-center gap-4 pt-6 border-t border-border/40">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={handleReset}
            className="rounded-lg h-11 px-5 font-bold gap-2 text-xs tracking-widest text-muted-foreground/60 hover:bg-muted hover:text-foreground transition-all uppercase"
          >
            <RotateCcw size={16} />
            초기화
          </Button>
          <Button
            type="submit"
            size="sm"
            className="rounded-lg h-11 px-8 font-bold gap-2 shadow-lg shadow-primary/20 transition-all hover:-translate-y-1 text-xs tracking-widest uppercase"
          >
            <Search size={16} />
            조회
          </Button>
        </div>
      </form>
    </div>
  );
}

export const StandardSearchFilter = SmartSearchPanel;

'use client';

import React from 'react';
import { cn } from '@/lib/utils';
